diff --git a/src/main/java/org/apache/commons/codec/digest/HmacUtils.java b/src/main/java/org/apache/commons/codec/digest/HmacUtils.java
index 90dc337d3..89bceb6de 100644
--- a/src/main/java/org/apache/commons/codec/digest/HmacUtils.java
+++ b/src/main/java/org/apache/commons/codec/digest/HmacUtils.java
@@ -22 +21,0 @@ import java.io.File;
-import java.io.FileInputStream;
@@ -25,0 +25,2 @@ import java.nio.ByteBuffer;
+import java.nio.file.Files;
+import java.nio.file.Path;
@@ -974,3 +975 @@ public final class HmacUtils {
-        try (BufferedInputStream stream = new BufferedInputStream(new FileInputStream(valueToDigest))) {
-            return hmac(stream);
-        }
+        return hmac(valueToDigest.toPath());
@@ -995 +993,0 @@ public final class HmacUtils {
-
@@ -1001,0 +1000,15 @@ public final class HmacUtils {
+    /**
+     * Returns the digest for the file.
+     *
+     * @param valueToDigest the path to use
+     * @return the digest
+     * @throws IOException
+     *             If an I/O error occurs.
+     * @since 1.19.0
+     */
+    public byte[] hmac(final Path valueToDigest) throws IOException {
+        try (BufferedInputStream stream = new BufferedInputStream(Files.newInputStream(valueToDigest))) {
+            return hmac(stream);
+        }
+    }
+
@@ -1064,0 +1078,13 @@ public final class HmacUtils {
+    /**
+     * Returns the digest for the path.
+     *
+     * @param valueToDigest the path to use
+     * @return the digest as a hexadecimal String
+     * @throws IOException
+     *             If an I/O error occurs.
+     * @since 1.19.0
+     */
+    public String hmacHex(final Path valueToDigest) throws IOException {
+        return Hex.encodeHexString(hmac(valueToDigest));
+    }
+
